// These are editorial examples, not answers generated by an AI service.
const answers = {
  practice: 'Yes, with checks. I’d compare the answers with my course material.',
  reference: 'Only as a lead. I’d open the original publication and check that it supports the claim.',
  money: 'I’d pause. Call the person on a number I already know before doing anything.'
};

document.querySelectorAll('[data-scenario]').forEach((scenario) => {
  const buttons = scenario.querySelectorAll('[data-choice]');
  const answer = scenario.querySelector('.scenario-answer');
  buttons.forEach((button) => {
    button.addEventListener('click', () => {
      buttons.forEach((other) => {
        other.setAttribute('aria-pressed', String(other === button));
      });
      answer.textContent = answers[button.dataset.choice];
    });
  });
});
